import pytest

from minisheet.refs import Ref, parse_range, parse_ref, to_a1


# B§1 table rows
def test_parse_ref_b12():
    assert parse_ref("B12") == Ref(1, 11, False, False)


def test_parse_ref_absolute_max():
    assert parse_ref("$zz$9999") == Ref(701, 9998, True, True)


def test_parse_range_mixed_flags():
    assert parse_range("$C3:A$1") == (Ref(0, 0, False, True), Ref(2, 2, True, False))


def test_to_a1_absolute_col():
    assert to_a1(Ref(26, 0, True, False)) == "$AA1"


def test_parse_ref_a0_rejected():
    with pytest.raises(ValueError):
        parse_ref("A0")


def test_parse_ref_aaa1_rejected():
    with pytest.raises(ValueError):
        parse_ref("AAA1")


def test_parse_ref_a10000_rejected():
    with pytest.raises(ValueError):
        parse_ref("A10000")


# Review Focus
def test_a01_rejected():
    with pytest.raises(ValueError):
        parse_ref("A01")


def test_range_bare_cell():
    with pytest.raises(ValueError):
        parse_range("A1")


def test_to_a1_out_of_range():
    with pytest.raises(ValueError):
        to_a1(Ref(702, 0))


# Additional behaviour from B§1
def test_parse_ref_a1_is_origin():
    assert parse_ref("A1") == Ref(0, 0)


def test_parse_ref_case_insensitive_letters():
    assert parse_ref("zz9999") == Ref(701, 9998)


def test_parse_range_single_cell():
    assert parse_range("A1:A1") == (Ref(0, 0), Ref(0, 0))


def test_parse_range_tie_uses_first_corner_flag():
    # both corners share column A (min and max col tie) and row min/max
    # for rows: $A1 has row 0 (first), $A$3 has row 2 (second)
    assert parse_range("$A1:$A$3") == (Ref(0, 0, True, False), Ref(0, 2, True, True))


def test_to_a1_plain():
    assert to_a1(Ref(0, 0)) == "A1"


def test_to_a1_absolute_row():
    assert to_a1(Ref(701, 9998, True, True)) == "$ZZ$9999"

